<?php
namespace App\Modules\Orders\Application;
use App\Models\User;use App\Modules\Audit\Application\RecordAuditEvent;use App\Modules\Inventory\Domain\Models\InventoryBalance;use App\Modules\Orders\Domain\Enums\ReservationStatus;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\Orders\Domain\Models\SalesOrder;use DomainException;use Illuminate\Support\Facades\DB;
class CancelSalesOrder {public function __construct(private readonly RecordAuditEvent $audit){}public function execute(SalesOrder $order,User $actor,string $reason):SalesOrder{if(trim($reason)==='')throw new DomainException('La cancelación requiere motivo.');return DB::transaction(function()use($order,$actor,$reason){$order=SalesOrder::query()->with('lines.reservations')->lockForUpdate()->findOrFail($order->id);if(in_array($order->status,[SalesOrderStatus::Delivered,SalesOrderStatus::Cancelled],true))throw new DomainException('El pedido ya no puede cancelarse.');if($order->advance_amount>0)throw new DomainException('Primero debe devolverse o aplicar el anticipo antes de cancelar.');foreach($order->lines as $line){foreach($line->reservations->where('status',ReservationStatus::Active) as $reservation){$balance=InventoryBalance::query()->where('presentation_id',$reservation->presentation_id)->lockForUpdate()->sole();$balance->update(['reserved_quantity'=>max(0,(float)$balance->reserved_quantity-(float)$reservation->quantity)]);$reservation->update(['status'=>ReservationStatus::Released,'released_at'=>now()]);}$line->update(['reserved_quantity'=>0]);}$from=$order->status;$order->update(['status'=>SalesOrderStatus::Cancelled]);$order->histories()->create(['from_status'=>$from->value,'to_status'=>SalesOrderStatus::Cancelled->value,'changed_by'=>$actor->id,'changed_at'=>now(),'notes'=>$reason]);$this->audit->execute('orders.cancelled',$order,$actor,after:['reason'=>$reason]);return $order->fresh();});}}
